import { parseTime } from './time.ts';

// One time from the booking form, or a list of times from the CSV import.
export function toMinutes(x: string | readonly string[]): number | number[] {
  return typeof x === 'string' ? parseTime(x) : x.map((t) => parseTime(t));
}

// Convert between "HH:MM" and minutes since 00:00.
export function parseTime(text: string): number {
  const m = /^([0-9]{2}):([0-9]{2})$/.exec(text);
  if (!m) throw new TypeError('Invalid time "' + text + '", expected HH:MM');
  const h = Number(m[1]);
  const min = Number(m[2]);
  if (h > 23 || min > 59) throw new RangeError('Time out of range: ' + text);
  return h * 60 + min;
}

export function formatTime(minutes: number): string {
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { toMinutes } from '../src/minutes.ts';

test('one time: 08:00 is minute 480', () => assert.equal(toMinutes('08:00'), 480));
test('a list: [07:00, 21:00] is [420, 1260]', () => assert.deepEqual(toMinutes(['07:00', '21:00']), [420, 1260]));

