export type Problem = { code: string; message: string };
export type Rule = (seats: number) => Problem | null;

// Runs every rule; calls onProblem for each problem found.
export function validate(seats: number, rules: readonly Rule[], onProblem?: (p: Problem) => undefined): Problem[] {
  const problems: Problem[] = [];
  for (const rule of rules) {
    const p = rule(seats);
    if (p === null) continue;
    problems.push(p);
    onProblem?.(p);
  }
  return problems;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { validate } from '../src/validate.ts';
import type { Problem, Rule } from '../src/validate.ts';

const tooMany: Rule = (seats) => (seats > 40 ? { code: 'TOO_MANY_SEATS', message: 'At most 40 seats' } : null);

test('the callback sees each problem', () => {
  const log: Problem[] = [];
  const problems = validate(45, [tooMany], (p) => log.push(p));
  assert.equal(problems.length, 1);
  assert.deepEqual(log, problems);
});
test('no problem, no call', () => {
  let calls = 0;
  validate(30, [tooMany], () => { calls++; });
  assert.equal(calls, 0);
});

import { validate } from '../src/validate.ts';
import type { Problem, Rule } from '../src/validate.ts';

const tooMany: Rule = (seats) => (seats > 40 ? { code: 'TOO_MANY_SEATS', message: 'At most 40 seats' } : null);
const log: Problem[] = [];
validate(45, [tooMany], (p) => log.push(p));            // push returns a number: ignored
validate(45, [tooMany], (p) => console.log(p.code));    // console.log returns undefined
validate(45, [tooMany]);                                // no callback at all

import { validate } from '../src/validate.ts';
import type { Rule } from '../src/validate.ts';

const tooMany: Rule = (seats) => (seats > 40 ? { code: 'TOO_MANY_SEATS', message: 'At most 40 seats' } : null);
validate(45, [tooMany], (code: number) => code); // expect TS2345
const first = validate(45, [tooMany], () => {}).at(0);
first.message; // expect TS18048

