export type Problem = { code: string; message: string };

// Sends one e-mail per problem to the lab admin. Returns how many were sent.
export function notifyAll(problems: readonly Problem[], send: (p: Problem) => Promise<void>): number {
  let sent = 0;
  problems.forEach(async (p) => {
    await send(p);
    sent++;
  });
  return sent;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { notifyAll } from '../src/notify.ts';
import type { Problem } from '../src/notify.ts';

const problems: Problem[] = [
  { code: 'OFF_GRID', message: 'Use the 30-minute grid' },
  { code: 'TOO_LONG', message: 'At most 4 hours' },
];
const wait = () => new Promise<void>((resolve) => setTimeout(resolve, 5));

test('every e-mail is sent before notifyAll resolves', async () => {
  const outbox: string[] = [];
  const sent = await notifyAll(problems, async (p) => { await wait(); outbox.push(p.code); });
  assert.equal(sent, 2);
  assert.deepEqual(outbox, ['OFF_GRID', 'TOO_LONG']);
});
test('a failing send rejects notifyAll — the caller can answer 503', async () => {
  await assert.rejects(notifyAll(problems, async () => { await wait(); throw new Error('SMTP is down'); }), /SMTP is down/);
});

import { notifyAll } from '../src/notify.ts';

const sent: number = await notifyAll([], async () => {});
console.log(sent);

