export type Problem = { code: string; message: string };

// Sends one e-mail per problem to the lab admin. Resolves with how many were sent.
// forEach would start every send and wait for none: a failure would be an unhandled rejection.
// A for…of loop with await waits for each send, and a failure rejects the returned promise.
export async function notifyAll(problems: readonly Problem[], send: (p: Problem) => Promise<void>): Promise<number> {
  let sent = 0;
  for (const p of problems) {
    await send(p);
    sent++;
  }
  return sent;
}

